package com.utewedding.app.domain.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="support_idempotency")public class SupportIdempotencyEntity{@EmbeddedId private SupportIdempotencyId id;@Column(name="request_hash",nullable=false,length=64)private String requestHash;@Column(name="ticket_id")private UUID ticketId;@Column(name="message_id")private UUID messageId;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;protected SupportIdempotencyEntity(){}public SupportIdempotencyEntity(SupportIdempotencyId i,String h,UUID t,UUID m){id=i;requestHash=h;ticketId=t;messageId=m;createdAt=Instant.now();}public String getRequestHash(){return requestHash;}public UUID getTicketId(){return ticketId;}public UUID getMessageId(){return messageId;}}
